**Padrão Observer:**

Define dependência um-para-muitos. Quando um objeto muda, todos os dependentes são notificados.

```python
from abc import ABC, abstractmethod
from typing import List, Any

class Observer(ABC):
    @abstractmethod
    def update(self, event: str, data: Any):
        pass

class Subject:
    def __init__(self):
        self._observers: List[Observer] = []

    def attach(self, observer: Observer):
        if observer not in self._observers:
            self._observers.append(observer)

    def detach(self, observer: Observer):
        self._observers.remove(observer)

    def notify(self, event: str, data: Any):
        for observer in self._observers:
            observer.update(event, data)

class EventManager(Subject):
    def emit(self, event: str, data: Any = None):
        self.notify(event, data)

class EmailNotifier(Observer):
    def update(self, event: str, data: Any):
        if event == "user_registered":
            print(f"[Email] Bem-vindo, {data['email']}!")

class Logger(Observer):
    def update(self, event: str, data: Any):
        print(f"[Log] {event}: {data}")

events = EventManager()
events.attach(EmailNotifier())
events.attach(Logger())
events.emit("user_registered", {"email": "user@example.com"})
```

**Padrão Singleton:**

Garante que uma classe tenha apenas uma instância e fornece acesso global a ela.

```python
# Método 1: Usando __new__
class Singleton:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

# Método 2: Thread-safe com lock
import threading

class ThreadSafeSingleton:
    _instance = None
    _lock = threading.Lock()

    def __new__(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
        return cls._instance

# Método 3: Decorator
def singleton(cls):
    instances = {}
    lock = threading.Lock()

    def wrapper(*args, **kwargs):
        if cls not in instances:
            with lock:
                if cls not in instances:
                    instances[cls] = cls(*args, **kwargs)
        return instances[cls]
    return wrapper

@singleton
class Database:
    def __init__(self):
        self.connection = None
