**Análise de Resource Leak:**

**Código problemático:**
```python
def process_orders():
    conn = db.connect()  # Resource adquirido
    cursor = conn.cursor()  # Outro resource

    orders = cursor.execute("SELECT * FROM orders")

    for order in orders:
        if order['status'] == 'pending':
            process(order)  # Pode lançar exceção!

    conn.close()  # Nunca executa se exception ocorrer
```

**Problemas:**
1. Se `process(order)` lançar exceção, `conn.close()` nunca executa
2. Cursor também não é fechado
3. Conexão permanece aberta até GC (pode nunca ocorrer)
4. Em escala, pool de conexões esgota

**Solução 1: Try-Finally (Python)**
```python
def process_orders_safe():
    conn = None
    cursor = None

    try:
        conn = db.connect()
        cursor = conn.cursor()

        orders = cursor.execute("SELECT * FROM orders")

        for order in orders:
            if order['status'] == 'pending':
                process(order)

        conn.commit()

    except Exception as e:
        if conn:
            conn.rollback()
        raise

    finally:
        # Garante cleanup mesmo com exceção
        if cursor:
            cursor.close()
        if conn:
            conn.close()
```

**Solução 2: Context Manager (Python - melhor)**
```python
from contextlib import contextmanager

@contextmanager
def db_connection():
    """Context manager para conexão segura"""
    conn = db.connect()
    try:
        yield conn
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()

@contextmanager
def db_cursor(conn):
    cursor = conn.cursor()
    try:
        yield cursor
    finally:
        cursor.close()

# Uso limpo
def process_orders_clean():
    with db_connection() as conn:
        with db_cursor(conn) as cursor:
            orders = cursor.execute("SELECT * FROM orders")
            for order in orders:
                if order['status'] == 'pending':
                    process(order)
            conn.commit()

# Múltiplos resources
from contextlib import ExitStack

def complex_operation():
    with ExitStack() as stack:
        conn = stack.enter_context(db_connection())
        cursor = stack.enter_context(db_cursor(conn))
        file = stack.enter_context(open('log.txt', 'w'))

        # Todos são fechados automaticamente no final
        # Mesmo se exceção ocorrer
```

**Solução 3: RAII em C++**
```cpp
// ANTES (leak)
void processOrders() {
    Connection* conn = db.connect();
    Cursor* cursor = conn->cursor();

    // ... process ...

    delete cursor;  // Esquecido em early return
    delete conn;
}

// DEPOIS (RAII com smart pointers)
class ConnectionGuard {
    std::unique_ptr<Connection> conn;

public:
    explicit ConnectionGuard(std::unique_ptr<Connection> c)
        : conn(std::move(c)) {}

    ~ConnectionGuard() {
        if (conn) conn->close();
    }

    Connection* get() const { return conn.get(); }

    // Movable, not copyable
    ConnectionGuard(ConnectionGuard&&) = default;
    ConnectionGuard& operator=(ConnectionGuard&&) = default;
};

void processOrdersSafe() {
    auto conn = std::make_unique<Connection>(db.connect());
    ConnectionGuard guard(std::move(conn));

    auto cursor = std::make_unique<Cursor>(guard.get()->cursor());

    // ... process ...

    // Automatic cleanup em qualquer ponto de saída
}

// Ou com scope guard (C++17)
template<typename F>
class ScopeGuard {
    F func;
    bool active = true;
public:
    explicit ScopeGuard(F f) : func(std::move(f)) {}
    ~ScopeGuard() { if (active) func(); }
    void dismiss() { active = false; }
};

void processOrders() {
    auto* conn = db.connect();
    auto guard = ScopeGuard([conn]() { conn->close(); });

    // ... use conn ...

    // Fechado automaticamente
}
```

**Solução 4: RAII em Rust (ownership system)**
```rust
// Rust garante cleanup via Drop trait
struct DbConnection {
    handle: *mut Connection,
}

impl Drop for DbConnection {
    fn drop(&mut self) {
        unsafe {
            (*self.handle).close();
        }
    }
}

fn process_orders() -> Result<(), Error> {
    let conn = DbConnection::connect()?;  // RAII
    let cursor = conn.cursor()?;  // RAII

    for order in cursor.execute("SELECT * FROM orders")? {
        if order.status == "pending" {
            process(order)?;
        }
    }

    conn.commit()?;

    // conn e cursor são dropped automaticamente aqui
    // Mesmo se ? retornar early!
    Ok(())
}
```

**Solução 5: Java try-with-resources**
```java
// ANTES (leak)
void processOrders() throws SQLException {
    Connection conn = dataSource.getConnection();
    Statement stmt = conn.createStatement();
    ResultSet rs = stmt.executeQuery("SELECT * FROM orders");

    while (rs.next()) {
        process(rs);  // Pode lançar exception
    }

    // Se exception, nunca fecha
    rs.close();
    stmt.close();
    conn.close();
}

// DEPOIS (try-with-resources)
void processOrdersSafe() throws SQLException {
    try (Connection conn = dataSource.getConnection();
         Statement stmt = conn.createStatement();
         ResultSet rs = stmt.executeQuery("SELECT * FROM orders")) {

        while (rs.next()) {
            process(rs);
        }

        conn.commit();

    }  // Auto-close: rs, stmt, conn (na ordem inversa)
    catch (Exception e) {
        // conn já foi fechado, mas não commitado
        throw e;
    }
}
```

