builder.add_node('image_processor', image_processor); builder.add_node('text_processor', text_processor)
builder.add_node('aggregate', aggregate)
builder.add_edge(START, 'router'); builder.add_edge('pdf_processor', 'aggregate')
builder.add_edge('image_processor', 'aggregate'); builder.add_edge('text_processor', 'aggregate')
builder.add_edge('aggregate', END)

Router direciona para especialista certo. Processamento em paralelo via Send. Agregacao no final.

Guardians sao agentes que validam entrada/saida para seguranca:

from langgraph.graph import StateGraph, START, END
from langgraph.types import Command

def input_guard(state):
    msg = state['messages'][-1].content
    if contains_pii(msg): return Command(goto='reject', update={'reason': 'PII detectado'})
    if contains_injection(msg): return Command(goto='reject', update={'reason': 'Prompt injection detectado'})
    return Command(goto='processor')

def output_guard(state):
    output = state.get('result', '')
    if contains_sensitive(output): return Command(goto='sanitizer')
    return Command(goto='end')

def sanitizer(state):
    clean = redact_sensitive(state.get('result', ''))
    return {'result': clean}

builder = StateGraph(State)
builder.add_node('input_guard', input_guard)
builder.add_node('processor', processor_agent)
builder.add_node('output_guard', output_guard)
builder.add_node('sanitizer', sanitizer)
builder.add_edge(START, 'input_guard')
builder.add_edge('input_guard', 'processor')  # ou 'reject'
builder.add_edge('processor', 'output_guard')
builder.add_edge('output_guard', 'end')  # ou 'sanitizer' -> 'end'

Camada de seguranca sem modificar agentes de negocio. Input guard filtra PII e injection. Output guard redact dados sensiveis.

import asyncio
from dataclasses import dataclass
from datetime import datetime

@dataclass
class CostEntry:
    agent_id: str; tokens_in: int; tokens_out: int; model: str; timestamp: datetime

class CostTracker:
    def __init__(self, price_per_1k_input=0.03, price_per_1k_output=0.06):
        self.entries = []
        self.price_in = price_per_1k_input
        self.price_out = price_per_1k_output
    def record(self, agent_id, tokens_in, tokens_out, model='gpt-4'):
        self.entries.append(CostEntry(agent_id, tokens_in, tokens_out, model, datetime.now()))
    def cost_by_agent(self) -> dict:
        costs = {}
        for e in self.entries:
            c = (e.tokens_in * self.price_in + e.tokens_out * self.price_out) / 1000
            costs[e.agent_id] = costs.get(e.agent_id, 0) + c
        return costs
    def total_cost(self) -> float:
        return sum((e.tokens_in * self.price_in + e.tokens_out * self.price_out) / 1000 for e in self.entries)
    def budget_remaining(self, budget: float) -> float:
        return budget - self.total_cost()

tracker = CostTracker()
tracker.record('researcher', 500, 200, 'gpt-4')
tracker.record('coder', 800, 400, 'gpt-4')
print(tracker.cost_by_agent())  # {'researcher': 0.027, 'coder': 0.048}
print(tracker.total_cost())  # 0.075

import asyncio
from langgraph.graph import StateGraph, START, END
from langgraph.types import Command

class TimeoutState(TypedDict):
    messages: list; result: str; timed_out_agents: list[str]

def agent_with_timeout(agent_id, timeout_seconds=30):
    async def node(state):
        if agent_id in state.get('timed_out_agents', []):
            return Command(goto='fallback', update={'result': 'Usando resposta de fallback'})
        try:
            result = await asyncio.wait_for(
                call_agent(agent_id, state),
                timeout=timeout_seconds
            )
            return {'result': result}
        except asyncio.TimeoutError:
            timed = state.get('timed_out_agents', []) + [agent_id]
            return Command(goto='fallback', update={'timed_out_agents': timed, 'result': f'{agent_id} demorou demais'})
    return node

Use asyncio.wait_for para timeout por chamada. Registre timed_out_agents para nao tentar o mesmo agente de novo. Faca fallback para agente mais simples (menor latencia) ou para resposta cacheada.

from langgraph.graph import StateGraph, START, END

class ConditionalState(TypedDict):
    query: str; complexity: str; result: str

def complexity_analyzer(state):
    query = state['query']
    word_count = len(query.split())
    if word_count > 50 or any(w in query for w in ['analise', 'compare', 'explique detalhadamente']):
        return {'complexity': 'high'}
    return {'complexity': 'low'}

def router(state):
    if state['complexity'] == 'high':
        return 'complex_agent'
    return 'simple_agent'

def complex_agent(state): return {'result': f'Resposta detalhada para: {state["query"]}'}
def simple_agent(state): return {'result': f'Resposta rapida para: {state["query"]}'}

builder = StateGraph(ConditionalState)
builder.add_node('analyzer', complexity_analyzer)
builder.add_node('complex_agent', complex_agent)
builder.add_node('simple_agent', simple_agent)
builder.add_edge(START, 'analyzer')
builder.add_conditional_edges('analyzer', router)
builder.add_edge('complex_agent', END)
builder.add_edge('simple_agent', END)
graph = builder.compile()

Analisa complexidade primeiro, depois roteia. Alta complexidade: agente com modelo maior e mais tempo. Baixa complexidade: agente rapido e barato. Economia de ate 70% em tokens.

