import json
from datetime import datetime
from typing import Any

class AuditLog:
    def __init__(self):
        self.entries = []
    def log(self, agent_id: str, action: str, input_data: Any, output_data: Any, metadata: dict = None):
        entry = {
            'timestamp': datetime.now().isoformat(),
            'agent_id': agent_id,
            'action': action,
            'input_hash': hash(str(input_data)),
            'output_hash': hash(str(output_data)),
            'metadata': metadata or {}
        }
        self.entries.append(entry)
    def get_agent_trace(self, agent_id: str) -> list:
        return [e for e in self.entries if e['agent_id'] == agent_id]
    def get_full_trace(self) -> list:
        return self.entries
    def export(self, filepath: str):
        with open(filepath, 'w') as f:
            json.dump(self.entries, f, indent=2, default=str)

class AuditedAgent:
    def __init__(self, agent_id, agent, audit: AuditLog):
        self.agent_id = agent_id; self.agent = agent; self.audit = audit
    async def run(self, input_data):
        self.audit.log(self.agent_id, 'input', input_data, None)
        result = await self.agent.ainvoke(input_data)
        self.audit.log(self.agent_id, 'output', input_data, result)
        return result

Para compliance, armazene hashes (nao conteudo completo) e permita reconstituicao via checkpoints. Exporte para JSON para analise externa.

import asyncio
from dataclasses import dataclass

@dataclass
class AgentWorker:
    id: str; agent: object; busy: bool = False; tasks_completed: int = 0

class LoadBalancer:
    def __init__(self, workers: list[AgentWorker]):
        self.workers = workers; self.queue = asyncio.Queue()
    def _select_worker(self, strategy='least_busy') -> AgentWorker:
        available = [w for w in self.workers if not w.busy]
        if not available: return None
        if strategy == 'least_busy':
            return min(available, key=lambda w: w.tasks_completed)
        elif strategy == 'random':
            import random; return random.choice(available)
        elif strategy == 'round_robin':
            return available[self._rr_counter % len(available)]
    async def submit(self, task):
        await self.queue.put(task)
    async def run(self):
        while True:
            task = await self.queue.get()
            worker = self._select_worker()
            if worker:
                worker.busy = True
                try:
                    result = await worker.agent.ainvoke(task)
                    worker.tasks_completed += 1
                finally:
                    worker.busy = False
            else:
                await self.queue.put(task)
                await asyncio.sleep(1)

Estrategias: least_busy (menos tarefas completadas), random, round_robin. Ideal quando multiplos agentes podem processar o mesmo tipo de tarefa.

```python
def analise_sentimento_lexico(texto: str) -> dict:
    """Análise de sentimento baseada em léxico para português."""

    lexico_positivo = {
        'bom': 1.0, 'ótimo': 1.5, 'excelente': 2.0, 'amar': 1.5,
        'feliz': 1.2, 'adorei': 1.8, 'maravilhoso': 2.0, 'gostei': 1.0,
        'incrível': 1.8, 'perfeito': 2.0, 'recomendo': 1.3, 'lindo': 1.5,
        'obrigado': 0.8, 'parabéns': 1.5, 'sucesso': 1.2
    }

    lexico_negativo = {
        'ruim': -1.0, 'péssimo': -1.5, 'horrível': -2.0, 'odiar': -1.5,
        'triste': -1.2, 'detestei': -1.8, 'terrível': -2.0, 'frustrado': -1.3,
        'decepcionado': -1.5, 'lixo': -2.0, 'nunca': -0.5, 'problema': -0.8,
        'falha': -1.0, 'erro': -0.8, 'pior': -1.5
    }

    # Normalizar texto
    palavras = texto.lower().split()

    score = 0.0
    palavras_encontradas = []

    for palavra in palavras:
        # Remover pontuação básica
        limpa = palavra.strip('.,!?;:')
        if limpa in lexico_positivo:
            score += lexico_positivo[limpa]
            palavras_encontradas.append((limpa, lexico_positivo[limpa]))
        elif limpa in lexico_negativo:
            score += lexico_negativo[limpa]
            palavras_encontradas.append((limpa, lexico_negativo[limpa]))

    # Classificação
    if score > 0.5:
        sentimento = 'positivo'
    elif score < -0.5:
        sentimento = 'negativo'
    else:
        sentimento = 'neutro'

    return {
        'sentimento': sentimento,
        'score': round(score, 2),
        'palavras_detectadas': palavras_encontradas
    }

# Exemplo de uso
resultado = analise_sentimento_lexico('O filme foi incrível, mas o final foi decepcionado.')
print(resultado)
# {'sentimento': 'neutro', 'score': 0.3, 'palavras_detectadas': [('incrível', 1.8), ('decepcionado', -1.5)]}
```

Limitações desta abordagem: não captura negação ('não foi bom'), ironia, intensificadores ('muito bom'), nem contexto. Modelos baseados em Transformers (como BERTimbau) resolvem a maioria desses problemas.

Para implementar JWT de forma segura em Node.js:

**1. Instale dependências**
```bash
npm install jsonwebtoken bcryptjs express-rate-limit
```

**2. Configuração segura de tokens**
```javascript
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

// Use variáveis de ambiente para segredos!
const JWT_SECRET = process.env.JWT_SECRET;  // Mínimo 256 bits
const JWT_EXPIRES_IN = '15m';  // Access token curto
const REFRESH_EXPIRES_IN = '7d';  // Refresh token mais longo

// Geração de token
function generateTokens(user) {
  const accessToken = jwt.sign(
    { userId: user.id, role: user.role },
    JWT_SECRET,
    { expiresIn: JWT_EXPIRES_IN, algorithm: 'HS256' }
  );

  const refreshToken = jwt.sign(
    { userId: user.id, type: 'refresh' },
    JWT_SECRET,
    { expiresIn: REFRESH_EXPIRES_IN }
  );

  return { accessToken, refreshToken };
}
```

**3. Middleware de verificação**
```javascript
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];  // Bearer TOKEN

  if (!token) {
    return res.sendStatus(401);
  }

  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.sendStatus(403);
  }
}
```

**4. Rate limiting em endpoints sensíveis**
```javascript
const rateLimit = require('express-rate-limit');

const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 minutos
  max: 5,  // 5 tentativas
  message: 'Muitas tentativas de login. Tente novamente mais tarde.'
});

app.post('/login', loginLimiter, async (req, res) => {
  // ...
});
```

**5. Armazenamento seguro de refresh tokens**
```javascript
// Armazene em banco de dados com hash
const crypto = require('crypto');

async function storeRefreshToken(userId, token) {
  const hashedToken = crypto.createHash('sha256').update(token).digest('hex');
  await db.query(
    'INSERT INTO refresh_tokens (user_id, token_hash, expires_at) VALUES ($1, $2, $3)',
    [userId, hashedToken, new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)]
  );
}
```

**6. Revogação de tokens**
```javascript
// Mantenha uma blacklist de tokens revogados (em produção use Redis)
const tokenBlacklist = new Set();

function revokeToken(token) {
  tokenBlacklist.add(token);
}

// No middleware de autenticação
if (tokenBlacklist.has(token)) {
  return res.sendStatus(403);
}
```

**Práticas essenciais:**
- Use HTTPS obrigatoriamente
- Tokens de acesso curtos (5-15 minutos)
- Armazene tokens em httpOnly cookies, não localStorage
- Implemente refresh token rotation
- Valide claims completamente (iss, aud, exp)
- Use algoritmo RS256 em vez de HS256 para múltiplos serviços
- Nunca transmita secrets em URLs

Configuração segura de HTTPS/TLS:

**1. Obtenha um certificado válido**
```bash
# Let's Encrypt (gratuito e recomendado)
sudo apt install certbot python3-certbot-nginx
sudo certbot --nginx -d seu-dominio.com
```

**2. Configuração Nginx segura**
```nginx
server {
    listen 443 ssl http2;
    server_name seu-dominio.com;

    # Certificados
    ssl_certificate /etc/letsencrypt/live/seu-dominio.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/seu-dominio.com/privkey.pem;

    # Protocolos e ciphers fortes
    ssl_protocols TLSv1.2 TLSv1.3;  # TLS 1.0/1.1 desabilitados
    ssl_ciphers 'ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384';
    ssl_prefer_server_ciphers off;

    # Perfect Forward Secrecy
    ssl_dhparam /etc/nginx/dhparam.pem;  # openssl dhparam -out dhparam.pem 4096

    # Session caching
    ssl_session_cache shared:SSL:50m;
    ssl_session_timeout 1d;
    ssl_session_tickets off;

    # OCSP Stapling
    ssl_stapling on;
    ssl_stapling_verify on;
    ssl_trusted_certificate /etc/letsencrypt/live/seu-dominio.com/chain.pem;
    resolver 8.8.8.8 8.8.4.4 valid=300s;
    resolver_timeout 5s;

    # Security headers
    add_header Strict-Transport-Security "max-age=63072000; includeSubDomains; preload" always;
    add_header X-Frame-Options DENY;
    add_header X-Content-Type-Options nosniff;

    # Redirect HTTP para HTTPS
    location / {
        proxy_pass http://localhost:3000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}

# Redirect HTTP para HTTPS
server {
    listen 80;
    server_name seu-dominio.com;
    return 301 https://$server_name$request_uri;
}
```

**3. Teste a configuração**
```bash
# Verifique a configuração
sudo nginx -t
sudo systemctl reload nginx

# Teste SSL com SSL Labs
curl -s https://www.ssllabs.com/ssltest/analyze.html?d=seu-dominio.com

# Local com OpenSSL
openssl s_client -connect seu-dominio.com:443 -servername seu-dominio.com
```

